//! Fixture access shared by the solver differential tests.

#![allow(dead_code)] // each test binary uses a subset of the helpers

use akantu_validation::reduce::NanMinMax;
use std::path::PathBuf;

use akantu_core::GlobalIdx;
use akantu_core::enums::MatrixType;
use akantu_linalg::SparseMatrixAij;
use akantu_validation::{Fixture, fixtures_root};
use sha2::{Digest, Sha256};

/// Every case directory below `fixtures/solver/<group>`.
pub fn cases(group: &str) -> Vec<Fixture> {
    let dir = fixtures_root().join("solver").join(group);
    let mut out: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("{}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.join("manifest.json").exists())
        .collect();
    out.sort();
    assert!(!out.is_empty(), "no case in {}", dir.display());
    out.iter()
        .map(|p| {
            let f = Fixture::open(p).unwrap();
            f.require_golden().unwrap();
            f.verify_checksums().unwrap();
            f
        })
        .collect()
}

pub fn f64s(f: &Fixture, name: &str) -> Vec<f64> {
    f.load_f64(name)
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
        .data
}

pub fn i64s(f: &Fixture, name: &str) -> Vec<i64> {
    f.load_i64(name)
        .unwrap_or_else(|e| panic!("{}: {name}: {e}", f.case_id()))
        .data
}

pub fn scalar_i(f: &Fixture, name: &str) -> i64 {
    i64s(f, name)[0]
}

pub fn param<'a>(f: &'a Fixture, key: &str) -> &'a serde_json::Value {
    &f.manifest().parameters[key]
}

pub fn param_str(f: &Fixture, key: &str) -> String {
    param(f, key)
        .as_str()
        .unwrap_or_else(|| panic!("{}: parameter {key}", f.case_id()))
        .to_owned()
}

pub fn input_bytes(f: &Fixture, role: &str) -> Vec<u8> {
    std::fs::read(f.input_path(role).unwrap()).unwrap()
}

pub fn has_input(f: &Fixture, role: &str) -> bool {
    f.manifest().inputs.iter().any(|i| i.role == role)
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    let d = Sha256::digest(bytes);
    d.iter().map(|b| format!("{b:02x}")).collect()
}

/// The probe's `coords_sha256`: SHA-256 of the 1-based rows then columns as
/// little-endian i64.
pub fn coords_digest(m: &SparseMatrixAij) -> String {
    let mut bytes = Vec::with_capacity(16 * m.nnz());
    for r in m.irn_one_based() {
        bytes.extend_from_slice(&r.to_le_bytes());
    }
    for c in m.jcn_one_based() {
        bytes.extend_from_slice(&c.to_le_bytes());
    }
    sha256_hex(&bytes)
}

/// SHA-256 of the values as little-endian f64.
pub fn values_digest(v: &[f64]) -> String {
    let mut bytes = Vec::with_capacity(8 * v.len());
    for x in v {
        // D-046: default NaNs canonicalised (no recorded digest changes)
        bytes.extend_from_slice(&akantu_validation::canonical_le_bytes(*x));
    }
    sha256_hex(&bytes)
}

/// Exact comparison with the oracle record (decision D-046: default NaNs
/// of either sign are identical, everything else bitwise).
pub fn same_bits(a: &[f64], b: &[f64]) -> bool {
    akantu_validation::exact::exact_slices_eq(b, a)
}

/// Number of entries whose bits differ, and the largest relative difference.
pub fn diff_stats(a: &[f64], b: &[f64]) -> (usize, f64) {
    let scale = b.iter().fold(0.0f64, |m, v| m.nan_max(v.abs()));
    let mut n = 0;
    let mut worst = 0.0f64;
    for (x, y) in a.iter().zip(b) {
        if !akantu_validation::exact_eq(*y, *x) {
            n += 1;
            worst = worst.nan_max((x - y).abs() / scale.max(f64::MIN_POSITIVE));
        }
    }
    (n, worst)
}

pub fn matrix_type(word: &str) -> MatrixType {
    match word {
        "sym" => MatrixType::Symmetric,
        "unsym" => MatrixType::Unsymmetric,
        w => panic!("unknown matrix type word {w}"),
    }
}

/// Recorded COO (1-based rows/cols as stored by the probe) of `prefix`.
pub fn coo(f: &Fixture, prefix: &str) -> (Vec<GlobalIdx>, Vec<GlobalIdx>, Vec<f64>) {
    (
        i64s(f, &format!("{prefix}/rows")),
        i64s(f, &format!("{prefix}/cols")),
        f64s(f, &format!("{prefix}/values")),
    )
}

/// Assert that `m` equals the recorded matrix `prefix` (whatever parts the
/// probe stored: full COO, values + coordinate digest, or digests only),
/// including the release counters, the order and the symmetry flag.
pub fn assert_matrix(f: &Fixture, prefix: &str, m: &SparseMatrixAij) {
    let cid = f.case_id();
    let p = &f.manifest().parameters;
    assert_eq!(
        m.nnz() as u64,
        p[format!("{prefix}/nnz")].as_u64().unwrap(),
        "{cid}: {prefix} nnz"
    );
    assert_eq!(
        coords_digest(m),
        p[format!("{prefix}/coords_sha256")].as_str().unwrap(),
        "{cid}: {prefix} coordinates"
    );
    if f.quantity(&format!("{prefix}/rows")).is_ok() {
        let (rows, cols, vals) = coo(f, prefix);
        assert_eq!(m.irn_one_based(), rows, "{cid}: {prefix} rows");
        assert_eq!(m.jcn_one_based(), cols, "{cid}: {prefix} cols");
        assert!(same_bits(m.values(), &vals), "{cid}: {prefix} values");
    } else if f.quantity(&format!("{prefix}/values")).is_ok() {
        let vals = f64s(f, &format!("{prefix}/values"));
        let (n, worst) = diff_stats(m.values(), &vals);
        assert!(
            same_bits(m.values(), &vals),
            "{cid}: {prefix} values: {n} differ, max rel {worst:e}"
        );
    } else {
        assert_eq!(
            values_digest(m.values()),
            p[format!("{prefix}/values_sha256")].as_str().unwrap(),
            "{cid}: {prefix} values digest"
        );
    }
    let rel = |k: &str| scalar_i(f, &format!("{prefix}/{k}"));
    assert_eq!(
        m.profile_release() as i64,
        rel("profile_release"),
        "{cid}: {prefix} profile release"
    );
    assert_eq!(
        m.value_release() as i64,
        rel("value_release"),
        "{cid}: {prefix} value release"
    );
    assert_eq!(m.size(), rel("size"), "{cid}: {prefix} size");
    assert_eq!(
        i64::from(m.matrix_type() == MatrixType::Symmetric),
        rel("symmetric"),
        "{cid}: {prefix} symmetry"
    );
}

/// Element equations and column-major element matrices of `name`.
pub fn elements(f: &Fixture, name: &str) -> (Vec<Vec<GlobalIdx>>, Vec<Vec<f64>>) {
    let eqs = f.load_i64("element_equations").unwrap();
    let (ne, nd) = (eqs.shape[0], eqs.shape[1]);
    let mats = f.load_f64(name).unwrap();
    assert_eq!(mats.shape, [ne, nd, nd]);
    let mut e_eq = Vec::with_capacity(ne);
    let mut e_mat = Vec::with_capacity(ne);
    for e in 0..ne {
        e_eq.push(eqs.data[e * nd..(e + 1) * nd].to_vec());
        let mut cm = vec![0.0; nd * nd];
        for r in 0..nd {
            for c in 0..nd {
                cm[r + c * nd] = mats.data[(e * nd + r) * nd + c];
            }
        }
        e_mat.push(cm);
    }
    (e_eq, e_mat)
}

/// `addToProfile` for every element, then `addValues` per element.
pub fn assemble(
    m: &mut SparseMatrixAij,
    eqs: &[Vec<GlobalIdx>],
    mats: &[Vec<f64>],
    ty: MatrixType,
) {
    for e in eqs {
        m.add_block_to_profile(e, e).unwrap();
    }
    for (e, k) in eqs.iter().zip(mats) {
        m.add_values(e, e, k, ty).unwrap();
    }
}

/// The Dirichlet-modified `K` of an `aij` case (upstream's assembly,
/// terms and `applyBoundary`, replayed; checked bitwise by `aij_oracle`).
pub fn replay_k_bc(f: &Fixture) -> SparseMatrixAij {
    let n: GlobalIdx = param(f, "system_size").as_i64().unwrap();
    let ktype = matrix_type(&param_str(f, "matrix_type"));
    let etype = matrix_type(&param_str(f, "elemental_matrix_type"));
    let (eqs, kes) = elements(f, "element_matrices");
    let mut k = SparseMatrixAij::new("K", n, ktype);
    k.set_symmetry_policy(akantu_linalg::SymmetryPolicy::UpstreamUpperSelection);
    assemble(&mut k, &eqs, &kes, etype);
    let (ti, tj, tv) = (
        i64s(f, "terms/i"),
        i64s(f, "terms/j"),
        f64s(f, "terms/values"),
    );
    for ((&i, &j), &v) in ti.iter().zip(&tj).zip(&tv) {
        k.add(i, j, 0.0 + v).unwrap();
    }
    let blocked: Vec<bool> = i64s(f, "blocked").iter().map(|&b| b != 0).collect();
    let layout = akantu_linalg::EquationLayout::serial(usize::try_from(n).unwrap()).unwrap();
    k.apply_boundary(&layout, &blocked, 1.0).unwrap();
    assert_matrix(f, "K_bc", &k);
    k
}
